import unittest

from assets import asset_key


class AssetKeyTests(unittest.TestCase):
    def test_normalizes_name_and_builds_storage_key(self):
        self.assertEqual(
            asset_key("  Hello--World\tV2  ", 3),
            "assets/v3/hello_world_v2.bin",
        )
        self.assertEqual(asset_key("Café/RAW", 1), "assets/v1/café/raw.bin")

    def test_rejects_invalid_revisions(self):
        for revision in (0, -1, 1.5, "1", True, None):
            with self.subTest(revision=revision):
                with self.assertRaises(ValueError):
                    asset_key("name", revision)

    def test_rejects_non_string_names(self):
        with self.assertRaises(TypeError):
            asset_key(123, 1)


if __name__ == "__main__":
    unittest.main()
